class CsService{static $inject=["$http"];constructor($http){this._$http=$http}allocateJobs(courierId,dispId,jobIds){return this._$http.post("job/Allocate?courierId="+courierId+"&dispId="+dispId+"&jobIds="+jobIds).then(response=>response)}addRestoreEvent(jobNo,clientId,contact,staffId,courierId,jobId,jobType,despatcherName){return this._$http.post("job/AddRestoreEvent?jobNo="+jobNo+"&clientId="+clientId+"&contact="+contact+"&staffId="+staffId+"&courierId="+courierId+"&jobId="+jobId+"&jobType="+jobType+"&despatcherName="+despatcherName).then(response=>response.data)}getPodJobs(courierId,clientId,wild,job,fromDate,toDate,pageIndex,pageSize){return this._$http.get("/Job/PODSearch?courierId="+courierId+"&clientId="+clientId+"&wild="+wild+"&job="+job+"&fromDate="+fromDate.toISOString()+"&toDate="+toDate.toISOString()+"&pageIndex="+pageIndex+"&pageSize="+pageSize).then(response=>response.data)}searchBulkJobs(courierId,clientId,job,wild,fromDate,toDate,pageIndex,pageSize){return this._$http.get("/Job/BulkSearch?courierId="+courierId+"&clientId="+clientId+"&job="+job+"&wild="+wild+"&fromDate="+fromDate.toISOString()+"&toDate="+toDate.toISOString()+"&pageIndex="+pageIndex+"&pageSize="+pageSize).then(response=>response.data)}searchPreBookJobs(courierId,clientId,wild,job,fromDate,toDate,pageIndex,pageSize){return this._$http.get("/Job/PreBookSearch?courierId="+courierId+"&clientId="+clientId+"&wild="+wild+"&job="+job+"&fromDate="+fromDate.toISOString()+"&toDate="+toDate.toISOString()+"&pageIndex="+pageIndex+"&pageSize="+pageSize).then(response=>response.data)}getCourierRoute(code,start,end){return this._$http.get("/courier/route?code="+code+"&start="+start.format("YYYY-MM-DDTHH:mm:ss")+"&end="+end.format("YYYY-MM-DDTHH:mm:ss")).then(response=>response.data)}getJobDetail(jobId){return this._$http.get("/Job/Detail?jobId="+jobId).then(response=>response.data)}getRelatedJobs(id,clientId){return this._$http.get("/Job/Related?parentId="+id+"&clientId="+clientId).then(response=>response.data)}getScanDetail(runDate,scan){return this._$http.get("/Job/ScanJobDetail?runDate="+runDate.toISOString()+"&scan="+scan).then(response=>response.data)}getPreBookDetail(preBookJobId){return this._$http.get("/Job/PreBookDetail?preBookJobId="+preBookJobId).then(response=>response.data)}getBulkJobDetail(bulkJobId){return this._$http.get("/Job/BulkDetail?bulkJobId="+bulkJobId).then(response=>response.data)}getActiveCouriers(){return this._$http.get("courier/active").then(response=>response.data)}getAllCouriers(){return this._$http.get("courier/AllActive").then(response=>response.data)}addEventNote(eventId,note){return this._$http.post("CS/AddEventNote?eventId="+eventId+"&note="+note+"&userName="+ClientName).then(response=>response.data)}validateSwapPOD(jobNumber){return this._$http.post("Job/ValidateSwapPOD?job="+jobNumber).then(response=>response.data)}restoreJobs(courierId,dispId,jobIds){return this._$http.post("job/RestoreJobs?courierId="+courierId+"&dispId="+dispId+"&jobIds="+jobIds).then(response=>response.data)}restoreSplitJobs(courierId,dispId,jobIds){return this._$http.post("job/RestoreSplitJobs?courierId="+courierId+"&dispId="+dispId+"&jobIds="+jobIds).then(response=>response.data)}swapPOD(jobNumber1,jobNumber2){return this._$http.post("Job/SwapPOD?job1="+jobNumber1+"&job2="+jobNumber2).then(response=>response.data)}closeEvent(eventId,userName){return this._$http.post("CS/CloseEvent?eventId="+eventId+"&userName="+`${ClientName}-${userName}`).then(response=>response.data)}reSendJobs(jobIds){return this._$http.post("job/ReSendSelected?jobIds="+jobIds).then(response=>response.data)}reAssignJobs(jobIds){return this._$http.post("job/ReAssignSelected?jobIds="+jobIds).then(response=>response.data)}sendPOD(jobId,email){return this._$http.get("job/SendPOD?jobId="+jobId+"&toEmail="+email).then(response=>response.data)}unSplitJob(jobId){return this._$http.post("job/UnSplitJob?jobId="+jobId).then(response=>response.data)}generateDirectLink(eventId,clientId){return this._$http.get("/CS/GenerateDirectLink?eventId="+eventId+"&clientId="+clientId).then(response=>response.data)}createEvent(data,notify){return this._$http({url:"book/CreateEvent?clientInternal="+ClientInternal+"&notify="+notify+"&clientName="+ClientName,method:"POST",data:data}).then(response=>response.data).catch(response=>{console.error("Book/CreateEvent error",response.status,response.data)})}getActiveClients(searchTerm){return this._$http.get("/home/ActiveClients?searchTerm="+searchTerm).then(response=>response.data)}getActiveCouriersSearch(searchTerm){return this._$http.get("/courier/AllActiveSearch?searchTerm="+searchTerm).then(response=>response.data)}doAPI(path,data){return this._$http.post(path,data).then(response=>response.data)}}angular.module("uDispatch").factory("uCSData",CsService);